import React, { useEffect, useState } from "react";
import Product from "./Product"; // Importe o componente Product
import "./ProductList.scss";

const ProductList = () => {
  const [products, setProducts] = useState([]); // Estado para armazenar os produtos

  useEffect(() => {
    // Faz a requisição para o arquivo JSON
    fetch("/products.json") // Caminho para o arquivo JSON na pasta public
      .then((response) => response.json()) // Converte a resposta para JSON
      .then((data) => {
        setProducts(data); // Atualiza o estado com os produtos
      })
      .catch((error) => {
        console.error("Erro ao carregar os produtos:", error);
      });
  }, []); // O array vazio garante que o useEffect só rode uma vez

  return (
    <div className="product-list">
      {products.map((product) => (
        <Product key={product.productId} product={product} /> // Renderiza cada produto
      ))}
    </div>
  );
};

export default ProductList;
